class Solution:
    def wallsAndGates(self, rooms: List[List[int]]) -> None:
        """
        Do not return anything, modify rooms in-place instead.
        """
        # start with gates
        # Then reach out to all rooms from each gate
        # save the val when find the smallest
        m, n = len(rooms), len(rooms[0])
        DIR = [0, 1, 0, -1, 0]
        queue = collections.deque()

        for i in range(m):
            for j in range(n):
                if rooms[i][j] == 0:
                    queue.append((i, j))

        span = 1
        seen = set(queue)
        while queue:
            k = len(queue)
            for _ in range(k):
                node = queue.popleft()
                for i in range(4):
                    nr, nc = node[0] + DIR[i], node[1] + DIR[i + 1]
                    if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in seen and rooms[nr][nc] > 0:
                        rooms[nr][nc] = min(rooms[nr][nc], span)
                        queue.append((nr, nc))
                        seen.add((nr, nc))

            span += 1

        return
